'Owner-only, explicit-click 2-factor JRDB pilot (no betting).'
HTML = '<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#09172b"><title>KEIBA NINE｜開催日・全Rの自動試算</title><link rel="stylesheet" href="/owner-auto-trial.css"></head><body><main><a href="/">← 本人用ホーム</a><h1>開催日・全Rの自動試算</h1><section><a href="/owner-auto-forecast">全場・全Rの自動暫定予想を開く →</a><p class="muted">この画面は2項目の根拠確認用です。全Rの3連単下書き・発走前保存はリンク先で確認できます。</p></section><p class="warning">JRDBの非公開APIに接続できた場合だけ、調教・近走の2項目から「研究用の暫定比較順」を自動計算します。<strong>実戦予想・AI総合評価・3連単の買い目ではありません</strong>。JRA公式出走表や取消の照合も未実施です。</p><section><h2>対象レース</h2><label for="trialDate">開催日</label><input id="trialDate" type="date"><label for="trialTrack">競馬場</label><select id="trialTrack"><option value="">競馬場を選択</option><option>札幌</option><option>函館</option><option>福島</option><option>新潟</option><option>東京</option><option>中山</option><option>中京</option><option>京都</option><option>阪神</option><option>小倉</option></select><label for="trialRace">レース</label><select id="trialRace"></select><p id="trialConnect" class="muted" role="status">本人用JRDB接続設定を確認しています。</p><button id="trialRun" disabled type="button">この1Rの調教・近走を自動試算</button><p id="trialStatus" class="muted" role="status">未実行。結果はこの画面だけで表示し、保存・購入しません。</p></section><section><h2>開催日・全場のまとめて試算（最大36R）</h2><p class="muted">上の日付にある開催全Rを、同一データでまとめて調教・近走2項目だけ比較します。番組・馬・調教・近走・開催馬場の5種類を各1回取得するので、レースごとに36回取得しません。提供元の馬場情報はJRA公式の確定情報とは別です。勝率や3連単は生成しません。</p><button id="trialDayRun" disabled type="button">選択日の全Rをまとめて試算</button><p id="trialDayStatus" class="muted" role="status">未実行。本人用のデータ取得はボタンを押したときだけです。</p><p id="trialDaySummary" role="status"></p><p class="muted">各Rの「10項目の資料状況」に加え、馬番ごとの過去3走の4角位置傾向も確認できます。位置取りの記録は今回の展開予想ではなく、総合評価や勝率にも換算しません。</p><div id="trialDayRaces" aria-label="日別・競馬場別の暫定2項目試算"></div></section><section><h2>1レース・2項目の暫定比較順</h2><p class="muted">各馬のS/A/B/Cは既存の未検証な独自仮説。総合S/A/B/Cや勝率に変換しません。同点は同順位、資料不足馬は順位を付けません。人気やオッズは使用しません。</p><div id="trialSummary" role="status"></div><div id="trialRows" aria-label="本人専用の2項目暫定試算"></div>\n<button id="trialGradeHandoff" disabled type="button">このRの調教・近走を手動5項目評価に仮入力（未確定）</button>\n<p id="trialGradeStatus" class="muted" role="status">APIで取得・照合できた3頭以上のレースだけ引き継げます。残り3項目は「未評価」のままで、総合ランク・3連単は作りません。</p><p class="warning">これを根拠に馬券を作成する機能はありません。今後、血統・展開・馬場・コース適性などの評価と公式照合ができてから、本番の自動予想へ進みます。</p></section><a href="/owner-races">36R一覧へ戻る</a></main><script src="/owner-auto-trial.js" defer></script></body></html>'

CSS = '*{box-sizing:border-box}html{color-scheme:dark}body{margin:0;background:#09172b;color:#eef4fb;font:16px/1.65 system-ui,sans-serif}main{max-width:690px;margin:auto;padding:18px 16px 55px}h1{font-size:24px;color:#f2d387}section{background:#142940;border:1px solid #45637f;border-radius:14px;padding:16px;margin:13px 0}h2{font-size:18px;margin:0 0 10px}p{overflow-wrap:anywhere}.muted{color:#c7d6e6;font-size:14px}.warning{background:#2c2926;border:1px solid #a88f57;border-radius:10px;padding:11px;font-size:14px;color:#ffe9b9}label{display:block;font-weight:700;margin-top:11px}button,input,select{width:100%;font:inherit;padding:12px;min-height:44px;background:#0b1d30;color:white;border:1px solid #819bb1;border-radius:10px;margin-top:5px}button{background:#e9c675;color:#172c3d;border:0;font-weight:800;margin-top:14px}button:disabled{opacity:.45}.trial-horse{background:#0a223a;border:1px solid #527390;border-radius:10px;margin:8px 0;padding:10px 13px}.trial-horse strong{color:#f2d38c}.trial-horse p{margin:4px 0;font-size:14px}.not-ready{color:#ffd0b9}a{color:#e7d38b}.trial-day-row{background:#0a223a;border:1px solid #527390;border-radius:10px;margin:9px 0;padding:10px}.trial-day-row summary{cursor:pointer;color:#f2d38c;font-weight:750}.trial-day-row p{margin:6px 0}.trial-mini{margin:5px 0;padding:6px 9px;background:#17324a;border-radius:6px;font-size:13px}.trial-day-caption{font-size:13px;color:#d6e3ee}.trial-source-details{border-top:1px solid #44627e;margin:9px 0;padding:5px 0}.trial-source-details summary{color:#c8deed;font-size:13px;font-weight:700}.trial-source-details p{margin:3px 0 3px 12px!important}.trial-source-details summary:focus-visible{outline:2px solid #e9d08b}.trial-front{border-inline-start:3px solid #edca79;padding-inline-start:10px;background:#283f50}.trial-grade-transfer{font-size:13px;padding:10px;background:#284865;color:#f9dd91;border:1px solid #99875c;margin-top:9px}.trial-grade-transfer:focus-visible{outline:2px solid #e9d08b}#trialGradeHandoff{margin-top:12px;background:#d3b970}'

JS = "(()=>{'use strict';\nconst $=id=>document.getElementById(id);\nconst MISSING={\n missing_training_indices:'調教：追切・仕上指数の片方または両方が不足',\n no_linked_training_record:'調教：この馬に照合できる資料なし',\n no_usable_history:'近走：評価に使える過去走なし',\n only_one_usable_run:'近走：使える資料が1走のみ（現基準は2走必要）',\n insufficient_scored_runs:'近走：着順と指数がそろう資料が2走未満',\n no_linked_recent_record:'近走：この馬に照合できる資料なし',\n training_unassessed:'調教：資料不足・理由の再確認が必要',\n recent_unassessed:'近走：資料不足・理由の再確認が必要'\n};\nfunction missingText(h){return (Array.isArray(h.missingReasons)?h.missingReasons:[])\n .filter(k=>Object.hasOwn(MISSING,k)).map(k=>MISSING[k]).join('／');}\nconst tracks=['札幌','函館','福島','新潟','東京','中山','中京','京都','阪神','小倉'];\nlet connected=false,seq=0,daySeq=0,dayBusy=false,oneBusy=false,oneRaceForGrade=null;\nfunction validDay(date){\n if(!/^20\\d{2}-\\d{2}-\\d{2}$/.test(date))return false;\n const t=new Date(date+'T12:00:00Z');\n return Number.isFinite(t.valueOf())&&t.toISOString().slice(0,10)===date;\n}\nfunction selected(){\n const date=$('trialDate').value,track=$('trialTrack').value,race=$('trialRace').value;\n if(!validDay(date)||!tracks.includes(track)||!/^(?:[1-9]|1[0-2])$/.test(race))\n  return null;\n return {date:date.replaceAll('-',''),track,race};\n}\nfunction update(){\n $('trialRun').disabled=!connected||!selected()||oneBusy;\n $('trialDayRun').disabled=!connected||!validDay($('trialDate').value)||dayBusy;\n}\nfunction clear(){\n seq++;oneRaceForGrade=null;\n $('trialGradeHandoff').disabled=true;\n $('trialGradeStatus').textContent='レースを変更しました。JRDBの仮評価は再計算が必要です。';\n $('trialRows').replaceChildren();\n $('trialSummary').textContent='';\n $('trialStatus').textContent='レースの選択が変わりました。試算を実行してください。';\n update();\n}\nasync function request(url){\n const r=await fetch(url,{credentials:'same-origin',\n  headers:{'X-Keiba-Request':'private','Accept':'application/json'},\n  cache:'no-store'});\n const data=await r.json();\n if(!r.ok)throw Error(data.error||'接続できません');\n return data;\n}\nfunction validateReply(d,selection){\n if(!d||d.version!=='owner-single-race-two-factor-trial-1'||\n  d.date!==selection.date||d.track!==selection.track||\n  d.race!==Number(selection.race)||d.predictionReady!==false||\n  d.bettingReady!==false||d.overallRankReady!==false||\n  d.autoTicketReady!==false||d.officialJraVerified!==false||\n  d.researchOnly!==true||d.unverifiedFactors!==8||\n  !Array.isArray(d.runners)||d.runners.length<1||d.runners.length>18||\n  d.runners.length!==d.runnersObserved||\n  !Number.isInteger(d.twoFactorComparable)||\n  d.twoFactorComparable+d.ungraded!==d.runners.length)\n  throw Error('安全な試算結果として検証できません。');\n const seen=new Set(),allowed=['S','A','B','C','未評価'];\n const gradePoints={S:4,A:3,B:2,C:1};\n let previous=-Infinity,previousRank=0,previousNumber=0,complete=0;\n for(const row of d.runners){\n  if(!Number.isInteger(row.horseNumber)||row.horseNumber<1||row.horseNumber>18||\n    seen.has(row.horseNumber)||!allowed.includes(row.trainingGrade)||\n    !allowed.includes(row.recentGrade)||row.provisionalOnly!==true)\n   throw Error('馬番・暫定評価を確認できません。');\n  seen.add(row.horseNumber);\n  const eligible=row.trainingGrade!=='未評価'&&row.recentGrade!=='未評価';\n  if(eligible){\n   complete++;\n   if(!Number.isInteger(row.twoFactorPoints)||\n     row.twoFactorPoints!==gradePoints[row.trainingGrade]+gradePoints[row.recentGrade]||\n     !Number.isInteger(row.comparisonRank)||row.comparisonRank<1||\n     previous===999)throw Error('暫定順位を確認できません。');\n   if(previous!==-Infinity&&\n      (row.twoFactorPoints>previous||\n       (row.twoFactorPoints===previous&&row.horseNumber<=previousNumber)))\n    throw Error('比較順が不正です。');\n   // Backend applies competition ranks: ties at 1,1 then 3 (not 1,2,3).\n   const requiredRank=row.twoFactorPoints===previous?previousRank:complete;\n   if(row.comparisonRank!==requiredRank)\n    throw Error('同点を含む暫定順位を確認できません。');\n   previous=row.twoFactorPoints;\n   previousNumber=row.horseNumber;\n   previousRank=row.comparisonRank;\n  }else{\n   if(row.twoFactorPoints!==null||row.comparisonRank!==null)\n    throw Error('不足項目が順位に混ざっています。');\n   previous=999;\n  }\n }\n if(complete!==d.twoFactorComparable)throw Error('採点件数が一致しません。');\n return true;\n}\n$('trialDate').value=new Date(Date.now()+9*3600000).toISOString().slice(0,10);\nfor(let i=1;i<=12;i++){\n const o=document.createElement('option');o.value=String(i);o.textContent=i+'R';\n $('trialRace').append(o);\n}\n// Receive ONLY race coordinates from the 36R dashboard; no paid data in URLs.\nconst incoming=typeof window!=='undefined'&&window.location&&\n  typeof window.location.hash==='string'?window.location.hash:'';\nif(incoming.startsWith('#select=v1&')&&incoming.length<=160){\n try{\n  const q=new URLSearchParams(incoming.slice(1));\n  if(q.size===4&&['select','date','track','race'].every(k=>q.has(k))&&\n     q.get('select')==='v1'&&validDay(q.get('date'))&&\n     tracks.includes(q.get('track'))&&\n     /^(?:[1-9]|1[0-2])$/.test(q.get('race'))){\n   $('trialDate').value=q.get('date');\n   $('trialTrack').value=q.get('track');\n   $('trialRace').value=q.get('race');\n  }\n }catch(_){/* Untrusted fragment ignored; no API request. */}\n}\nfunction resetDay(){\n daySeq++;dayBusy=false;\n $('trialDayRaces').replaceChildren();\n $('trialDaySummary').textContent='';\n $('trialDayStatus').textContent='開催日を変更しました。新しい日付の試算を実行してください。';\n clear();\n}\n$('trialDate').onchange=resetDay;$('trialTrack').onchange=clear;$('trialRace').onchange=clear;\n\nconst FACTOR_LABELS={\n training:'調教（独自暫定指数）',recent:'近走（独自暫定指数）',\n pace:'過去4角位置（展開予想ではない）',\n pedigree:'父・母父の記録',draw_weight:'枠・斤量の記録',\n rotation:'前走日の記録',jockey_stable:'騎手・調教師名の記録',\n body_condition:'馬体形状コード（当日馬体重ではない）',\n course_distance:'コース・距離適性（未評価）',ground:'馬場適性（未評価）'\n};\nfunction validateCoverage(row){\n const c=row.factorCoverage;\n if(!c||c.observedRunnerCount!==row.runnersObserved||\n    c.verifiedAbilityFactors!==0||c.notOverallGrades!==true||\n    !c.materialCountByFactor||typeof c.materialCountByFactor!=='object'||\n    Object.keys(c.materialCountByFactor).length!==10||\n    Object.keys(FACTOR_LABELS).some(k=>\n      !Object.hasOwn(c.materialCountByFactor,k)||\n      !Number.isInteger(c.materialCountByFactor[k])||\n      c.materialCountByFactor[k]<0||\n      c.materialCountByFactor[k]>row.runnersObserved)||\n    c.materialCountByFactor.course_distance!==0||\n    c.materialCountByFactor.ground!==0||\n    c.materialCountByFactor.training!==row.runners.filter(h=>h.trainingGrade!=='未評価').length||\n    c.materialCountByFactor.recent!==row.runners.filter(h=>h.recentGrade!=='未評価').length||\n    !Array.isArray(c.experimentalFactors)||c.experimentalFactors.join(',')!=='training,recent'||\n    !Array.isArray(c.uncheckedFactors)||c.uncheckedFactors.join(',')!=='course_distance,ground'||\n    !Array.isArray(c.observationOnlyFactors)||\n    c.observationOnlyFactors.join(',')!=='pace,pedigree,draw_weight,rotation,jockey_stable,body_condition')\n  throw Error('10項目の資料記録を安全に確認できません。');\n}\n\nfunction validateRaceContext(race){\n const c=race.raceContext;\n const surfaces=[null,'芝','ダート','障害'],turns=[null,'右','左','直線'];\n const goings=['未確認','良','稍重','重','不良'];\n if(!c||typeof c!=='object'||!surfaces.includes(c.surface)||\n    !turns.includes(c.turn)||!goings.includes(c.going)||\n    (c.distance_m!==null&&(!Number.isInteger(c.distance_m)||\n       c.distance_m<100||c.distance_m>10000))||\n    typeof c.courseInfoPresent!=='boolean'||\n    typeof c.goingAvailable!=='boolean'||\n    typeof c.conditionSnapshotPresent!=='boolean'||\n    typeof c.conditionUpdateRecorded!=='boolean'||\n    c.officialJraVerified!==false||\n    c.horseCourseSuitabilityAssessed!==false||\n    c.horseGoingSuitabilityAssessed!==false||\n    c.raceConditionsVerified!==false||\n    c.courseInfoPresent!==(c.surface!==null&&c.distance_m!==null&&c.turn!==null)||\n    c.goingAvailable!==(c.going!=='未確認')||\n    (!c.conditionSnapshotPresent&&(c.goingAvailable||c.conditionUpdateRecorded))||\n    (c.goingAvailable&&!['芝','ダート'].includes(c.surface)))\n  throw Error('コース・馬場資料の整合を確認できません。');\n}\n\n\nconst POSITION_LABELS={\n frontObserved:'前方での通過を複数回観測',\n backObserved:'後方寄りの通過を観測',\n mixedObserved:'前方・後方の両方を観測',\n insufficient:'4角位置の観測不足'\n};\nfunction validateHistoricalPosition(race){\n const summary=race.pastFourthCornerSummary;\n if(!summary||typeof summary!=='object'||\n    summary.researchOnly!==true||\n    summary.racePaceForecastAvailable!==false||\n    summary.notRunnerAbilityGrade!==true||\n    summary.minObservedRacesForCategory!==2||\n    !summary.categoryCounts||typeof summary.categoryCounts!=='object'||\n    Object.keys(summary.categoryCounts).length!==4)\n  throw Error('過去4角位置の集計を確認できません。');\n const observed={frontObserved:0,backObserved:0,mixedObserved:0,insufficient:0};\n for(const h of race.runners){\n  if(!Object.hasOwn(observed,h.pastFourthCornerObservation))\n   throw Error('馬番の過去4角位置の資料を確認できません。');\n  observed[h.pastFourthCornerObservation]++;\n }\n for(const label of Object.keys(observed)){\n  if(!Number.isInteger(summary.categoryCounts[label])||\n      summary.categoryCounts[label]!==observed[label])\n   throw Error('過去4角位置の集計と馬番が一致しません。');\n }\n if(race.factorCoverage.materialCountByFactor.pace!==\n    race.runnersObserved-observed.insufficient)\n  throw Error('過去4角位置の記録件数が一致しません。');\n}\n\nfunction validateDayReply(day,expectedDate){\n if(!day||day.version!=='owner-day-two-factor-trial-4'||\n    day.date!==expectedDate||day.researchOnly!==true||\n    day.predictionReady!==false||day.bettingReady!==false||\n    day.autoTicketReady!==false||day.officialJraVerified!==false||\n    day.overallRankReady!==false||\n    !Number.isInteger(day.raceCount)||day.raceCount<0||day.raceCount>36||\n    !Array.isArray(day.races)||day.races.length!==day.raceCount||\n    !Number.isInteger(day.runnerCount)||!Number.isInteger(day.twoFactorComparable)||\n    !Number.isInteger(day.ungraded)||\n    !Number.isInteger(day.courseInfoPresentCount)||\n    !Number.isInteger(day.goingAvailableCount)||\n    day.courseInfoPresentCount<0||day.courseInfoPresentCount>day.raceCount||\n    day.goingAvailableCount<0||day.goingAvailableCount>day.raceCount||\n    day.runnerCount>648||\n    day.runnerCount!==day.twoFactorComparable+day.ungraded)\n   throw Error('開催日一括試算の安全性を検証できません。');\n const ids=new Set(),tracksSeen=new Set();\n let count=0,comparable=0,missing=0,courseCount=0,goingCount=0;\n for(const race of day.races){\n  if(!race||!tracks.includes(race.track)||!Number.isInteger(race.race)||\n      race.race<1||race.race>12)throw Error('対象Rの形式が不正です。');\n  validateReply(race,{date:expectedDate,track:race.track,race:String(race.race)});\n  validateCoverage(race);\n  validateRaceContext(race);\n  validateHistoricalPosition(race);\n  courseCount+=Number(race.raceContext.courseInfoPresent);\n  goingCount+=Number(race.raceContext.goingAvailable);\n  const id=race.track+'|'+race.race;\n  if(ids.has(id))throw Error('同一Rが重複しています。');\n  ids.add(id);tracksSeen.add(race.track);\n  count+=race.runnersObserved;comparable+=race.twoFactorComparable;missing+=race.ungraded;\n }\n if(tracksSeen.size>3||count!==day.runnerCount||\n    comparable!==day.twoFactorComparable||missing!==day.ungraded||\n    courseCount!==day.courseInfoPresentCount||\n    goingCount!==day.goingAvailableCount)\n   throw Error('全場の件数と採点数が一致しません。');\n}\n\n// Derived grades only; no provider records, actual indices or horse names.\nconst RESEARCH_HANDOFF='keiba-nine-owner-research-scorecard-handoff-v1';\nfunction transferResearchGrades(race,expectedDate){\n if(typeof sessionStorage==='undefined')\n  throw Error('このブラウザーでは一時引き継ぎが使えません。');\n if(!race||race.researchOnly!==true||race.predictionReady!==false||\n    race.bettingReady!==false||race.officialJraVerified!==false||\n    !Array.isArray(race.runners)||race.runners.length<3||race.runners.length>18)\n  throw Error('このレースはまだ2項目の仮入力へ渡せません。');\n validateReply(race,{date:expectedDate,track:race.track,race:String(race.race)});\n const runners=race.runners.map(h=>({\n  number:h.horseNumber,training:h.trainingGrade,recent:h.recentGrade\n })).sort((a,b)=>a.number-b.number);\n if(!runners.some(h=>h.training!=='未評価'||h.recent!=='未評価'))\n  throw Error('調教・近走の仮評価が1頭もありません。');\n // Store only research grades, not source IDs, names, odds or paid metrics.\n const payload={\n  version:'jrdb-research-to-scorecard-v1',\n  createdAt:new Date().toISOString(),\n  date:expectedDate.slice(0,4)+'-'+expectedDate.slice(4,6)+'-'+expectedDate.slice(6,8),\n  track:race.track,race:race.race,\n  researchOnly:true,officialJraVerified:false,predictionReady:false,\n  runners\n };\n if(!confirm('JRDBの未検証な調教・近走だけを、本人用の手動5項目評価に仮入力しますか？\\n適性・血統・展開は未評価のままです。総合予想・馬券は作成しません。'))return;\n sessionStorage.setItem(RESEARCH_HANDOFF,JSON.stringify(payload));\n window.location.assign('/my-scorecard#research=v1');\n}\n$('trialGradeHandoff').onclick=()=>{\n const choice=selected(),d=oneRaceForGrade;\n if(!choice||!d||d.date!==choice.date||d.track!==choice.track||\n    d.race!==Number(choice.race)){\n  $('trialGradeHandoff').disabled=true;\n  $('trialGradeStatus').textContent='対象レースが変更されました。再試算が必要です。';return;\n }\n try{transferResearchGrades(d,choice.date);}\n catch(e){$('trialGradeStatus').textContent='仮入力できません：'+\n  (e instanceof Error?e.message:'内容を確認してください。');}\n};\n\n$('trialDayRun').onclick=async()=>{\n const date=$('trialDate').value;\n if(!connected||dayBusy||!validDay(date))return;\n const expectedDate=date.replaceAll('-',''),stamp=++daySeq;\n dayBusy=true;update();\n $('trialDayStatus').textContent='開催日全Rの資料を取得中。表示は本人用・研究用の暫定比較だけです。';\n $('trialDayRaces').replaceChildren();$('trialDaySummary').textContent='';\n try{\n  const data=await request('/api/jrdb/one-day-trial?date='+encodeURIComponent(expectedDate));\n  if(stamp!==daySeq||$('trialDate').value!==date)return;\n  validateDayReply(data,expectedDate);\n  // Only after the ENTIRE response passes validation is any runner shown.\n  $('trialDaySummary').textContent=date+'：'+data.raceCount+'R・'+\n    data.runnerCount+'頭のうち2項目比較可能 '+data.twoFactorComparable+\n    '頭／未評価 '+data.ungraded+'頭。コース資料 '+data.courseInfoPresentCount+\n    '/'+data.raceCount+'R・提供元馬場 '+data.goingAvailableCount+\n    '/'+data.raceCount+'R（JRA公式未照合）。総合ランク・買い目は未作成。';\n  for(const race of data.races){\n   const details=document.createElement('details');details.className='trial-day-row';\n   const summary=document.createElement('summary');\n   summary.textContent=race.track+race.race+'R｜'+race.runnersObserved+\n     '頭中 '+race.twoFactorComparable+'頭の2項目を比較'+\n     '｜過去4角・前方複数回 '+race.pastFourthCornerSummary.categoryCounts.frontObserved+\n     '頭（展開予想ではない）';\n   details.append(summary);\n   const disclaimer=document.createElement('p');disclaimer.className='trial-day-caption';\n   disclaimer.textContent='暫定の2項目比較。過去3走の4角位置が2走以上ある場合だけ傾向表示。前方とは4角4番手以内の観測で、今回の先行・展開予想ではありません。JRA公式照合・総合分析・3連単ではありません。';\n   details.append(disclaimer);\n   const context=document.createElement('p');context.className='trial-day-caption';\n   const conditions=race.raceContext;\n   const surface=conditions.surface||'芝・ダート未確認';\n   const metres=conditions.distance_m===null?'距離未確認':conditions.distance_m+'m';\n   const turn=conditions.turn||'回り未確認';\n   context.textContent='コース '+surface+' '+metres+' '+turn+\n     '｜提供元の馬場 '+conditions.going+\n     '｜記録更新日時 '+(conditions.conditionUpdateRecorded?'あり':'未記録')+\n     '｜JRA公式未照合・鮮度未検証・馬ごとの適性は未評価';\n   details.append(context);\n   const factors=document.createElement('details');factors.className='trial-source-details';\n   const label=document.createElement('summary');\n   label.textContent='10項目の資料記録（能力評価ではありません）';\n   factors.append(label);\n   for(const [code,title] of Object.entries(FACTOR_LABELS)){\n    const text=document.createElement('p');\n    const flag=['course_distance','ground'].includes(code)?'未チェック':\n      ['training','recent'].includes(code)?'独自暫定評価あり':'資料記録あり・能力未評価';\n    text.textContent=title+'｜'+race.factorCoverage.materialCountByFactor[code]+\n     '/'+race.runnersObserved+'頭｜'+flag;\n    text.className='trial-day-caption';\n    factors.append(text);\n   }\n   details.append(factors);\n   for(const h of race.runners){\n    const label=document.createElement('div');\n    label.className=h.pastFourthCornerObservation==='frontObserved'?\n      'trial-mini trial-front':'trial-mini';\n    label.textContent=h.horseNumber+'番｜'+\n      (h.comparisonRank===null?'比較順位なし':'暫定'+h.comparisonRank+'位')+\n      '｜調教'+h.trainingGrade+'・近走'+h.recentGrade+\n      '｜過去4角 '+POSITION_LABELS[h.pastFourthCornerObservation];\n    details.append(label);\n   }\n   if(race.runners.length>=3&&race.runners.some(h=>\n       h.trainingGrade!=='未評価'||h.recentGrade!=='未評価')){\n    const transfer=document.createElement('button');\n    transfer.type='button';transfer.className='trial-grade-transfer';\n    transfer.textContent='このRの調教・近走だけを手動5項目へ仮入力（未確定）';\n    transfer.onclick=()=>{\n     if(stamp!==daySeq||$('trialDate').value!==date){\n      $('trialDayStatus').textContent='対象日付が変更されました。全Rを再試算してください。';return;\n     }\n     try{transferResearchGrades(race,expectedDate);}\n     catch(e){$('trialDayStatus').textContent='仮入力できません：'+\n      (e instanceof Error?e.message:'内容を確認してください。');}\n    };\n    details.append(transfer);\n   }\n   $('trialDayRaces').append(details);\n  }\n  $('trialDayStatus').textContent=data.warning;\n }catch(e){\n  if(stamp===daySeq){\n   $('trialDayRaces').replaceChildren();$('trialDaySummary').textContent='';\n   $('trialDayStatus').textContent='全Rを試算できません：'+\n     (e instanceof Error?e.message:'接続とデータを確認してください。');\n  }\n }finally{\n  if(stamp===daySeq){dayBusy=false;update();}\n }\n};\n\n$('trialRun').onclick=async()=>{\n const choice=selected();if(!connected||!choice||oneBusy)return;\n const stamp=++seq;\n oneBusy=true;update();oneRaceForGrade=null;\n $('trialGradeHandoff').disabled=true;\n $('trialRows').replaceChildren();$('trialSummary').textContent='';\n $('trialStatus').textContent='この1RのJRDB資料を本人用サーバーで照合しています。';\n try{\n  const q=new URLSearchParams(choice);\n  const result=await request('/api/jrdb/one-race-trial?'+q.toString());\n  if(stamp!==seq||!selected()||selected().date!==choice.date||\n     selected().track!==choice.track||selected().race!==choice.race)return;\n  validateReply(result,choice);\n  $('trialSummary').textContent=choice.track+Number(choice.race)+'R：'+\n   result.runnersObserved+'頭のうち2項目比較可能 '+result.twoFactorComparable+'頭／未評価 '+\n   result.ungraded+'頭。総合ランク・買い目は未作成。';\n  for(const h of result.runners){\n   const card=document.createElement('div');card.className='trial-horse';\n   const head=document.createElement('strong');\n   head.textContent=h.comparisonRank===null?\n     h.horseNumber+'番｜順位未評価':\n     '暫定'+h.comparisonRank+'位｜'+h.horseNumber+'番';\n   const p=document.createElement('p');\n   p.textContent='調教 '+h.trainingGrade+'／近走 '+h.recentGrade+\n    (h.twoFactorPoints===null?'／2項目の比較不可':'／研究用2項目合計 '+h.twoFactorPoints);\n   card.append(head,p);\n   if(missingText(h)){const reason=document.createElement('p');reason.className='muted';reason.textContent=missingText(h);card.append(reason);}\n   $('trialRows').append(card);\n  }\n  if(result.runners.length>=3&&result.runners.some(h=>\n      h.trainingGrade!=='未評価'||h.recentGrade!=='未評価')){\n   oneRaceForGrade=result;$('trialGradeHandoff').disabled=false;\n   $('trialGradeStatus').textContent='本人がボタンを押した場合だけ、研究用の調教・近走を5項目評価へ渡します。';\n  }\n  $('trialStatus').textContent=result.warning;\n }catch(e){\n  if(stamp===seq)$('trialStatus').textContent='試算できません：'+\n   (e instanceof Error?e.message:'データを確認してください。');\n }finally{oneBusy=false;update();}\n};\nrequest('/api/status').then(s=>{\n connected=s.jrdbConfigured===true;\n $('trialConnect').textContent=connected?\n  '本人用JRDB認証情報の設定あり。接続や予想精度を保証するものではありません。':\n  'JRDB β版の専用API認証情報が未設定です。発行とRenderの非公開設定が必要です。';\n update();\n}).catch(()=>{\n connected=false;update();\n $('trialConnect').textContent='接続設定を確認できません。ログインと通信を確認してください。';\n});\n})();"
